/**
 * The ONE place where Baptist's HTTP headers are defined (spec A1).
 *
 * Every host reads its own config file, so `npm run gen:headers` turns this
 * file into:
 *   - public/_headers  (Cloudflare Pages, Netlify)
 *   - vercel.json      (Vercel)
 * The Vite preview server also reads it directly (see vite.config.js).
 * A unit test fails if the generated files ever drift from this one.
 */

/** Content-Security-Policy, one directive per line so it is easy to read. */
const CSP = [
  "default-src 'none'",
  // 'wasm-unsafe-eval' lets WebAssembly compile. It does NOT allow JS eval().
  "script-src 'self' 'wasm-unsafe-eval'",
  "worker-src 'self' blob:",
  "style-src 'self'",
  "img-src 'self' blob: data:",
  "media-src 'self' blob:",
  "font-src 'self'",
  "connect-src 'self'",
  "manifest-src 'self'",
  "base-uri 'none'",
  "form-action 'none'",
  "frame-ancestors 'none'",
  "object-src 'none'",
  // Trusted Types: only our "default" policy may exist (spec A5).
  "require-trusted-types-for 'script'",
  'trusted-types default',
].join('; ');

/** The three headers that make the page "cross-origin isolated". */
const ISOLATION_HEADERS = {
  'Cross-Origin-Opener-Policy': 'same-origin',
  'Cross-Origin-Embedder-Policy': 'require-corp',
  'Cross-Origin-Resource-Policy': 'same-origin',
};

/** Security headers sent with every response. */
const SECURITY_HEADERS = {
  'Content-Security-Policy': CSP,
  ...ISOLATION_HEADERS,
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'no-referrer',
  'Permissions-Policy':
    'camera=(), microphone=(), geolocation=(), payment=(), usb=(), browsing-topics=()',
  'Strict-Transport-Security': 'max-age=63072000; includeSubDomains; preload',
};

/** Files whose names contain a version or content hash never change. */
const IMMUTABLE = { 'Cache-Control': 'public, max-age=31536000, immutable' };

/**
 * Header rules. `path` uses the Netlify/Cloudflare `_headers` syntax, where a
 * trailing `*` matches anything. Later rules add to earlier ones.
 * @type {{ path: string, headers: Record<string, string> }[]}
 */
export const HEADER_RULES = [
  { path: '/*', headers: SECURITY_HEADERS },
  { path: '/assets/*', headers: IMMUTABLE }, // Vite's hashed JS/CSS
  { path: '/engines/*', headers: IMMUTABLE }, // versioned WASM engines
];

/**
 * Headers for the Vite dev server. The full CSP would block Vite's injected
 * styles and hot reload, so dev only gets what SharedArrayBuffer needs (A4).
 */
export const DEV_HEADERS = { ...ISOLATION_HEADERS };

/**
 * Does a `_headers`-style pattern match a URL path?
 * @param {string} pattern e.g. "/engines/*"
 * @param {string} pathname e.g. "/engines/magick.wasm"
 */
function matches(pattern, pathname) {
  if (pattern.endsWith('*')) return pathname.startsWith(pattern.slice(0, -1));
  return pathname === pattern;
}

/**
 * All headers that apply to one URL path (used by the preview server).
 * @param {string} pathname
 * @returns {Record<string, string>}
 */
export function headersForPath(pathname) {
  const result = {};
  for (const rule of HEADER_RULES) {
    if (matches(rule.path, pathname)) Object.assign(result, rule.headers);
  }
  return result;
}

/**
 * Build the text of a `_headers` file (Cloudflare Pages and Netlify format).
 * @param {typeof HEADER_RULES} rules
 * @returns {string}
 */
export function toNetlifyHeaders(rules) {
  const blocks = rules.map((rule) => {
    const lines = Object.entries(rule.headers).map(([name, value]) => `  ${name}: ${value}`);
    return [rule.path, ...lines].join('\n');
  });
  return `# GENERATED by scripts/gen-headers.js from security/headers.js. Do not edit.\n${blocks.join('\n\n')}\n`;
}

/**
 * Build the object for `vercel.json`. Vercel uses regex-like `source`
 * patterns, so "/engines/*" becomes "/engines/(.*)".
 * @param {typeof HEADER_RULES} rules
 */
export function toVercelConfig(rules) {
  return {
    $schema: 'https://openapi.vercel.sh/vercel.json',
    headers: rules.map((rule) => ({
      source: rule.path.replace(/\*$/, '(.*)'),
      headers: Object.entries(rule.headers).map(([key, value]) => ({ key, value })),
    })),
  };
}
